import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"14、【大有】 乾下离上","description":"子夏易传 - 14、【大有】 乾下离上","frontmatter":{"title":"14、【大有】 乾下离上","description":"子夏易传 - 14、【大有】 乾下离上"},"headers":[],"relativePath":"zh/classics/zixia/016.md","filePath":"zh/classics/zixia/016.md"}'),i={name:"zh/classics/zixia/016.md"};function r(_,p,c,o,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="_14、【大有】-乾下离上" tabindex="-1">14、【大有】 乾下离上 <a class="header-anchor" href="#_14、【大有】-乾下离上" aria-label="Permalink to “14、【大有】 乾下离上”">​</a></h1><p>卦辞：大有，元亨。</p><p>彖曰：大有，柔得尊位，大中而上下應之，曰大有。其德剛健，而文明應乎天，而時行是以，元亨。</p><p>子夏：柔得大中之位，而上下歸焉，無有逺邇，皆大有之也。其德剛健而行，文明以辨，大位德應於天，以時行，是以大亨也。</p><p>象曰：火在天上，大有。君子以遏惡揚善，順天休命。</p><p>子夏：明得其時，上無不容也。善者，道之大也，故揚之。惡者，道之小也，故遏之。上舉其善則惡止矣。君子順其時，美其命而已，故大有之也。</p><p>初九，无交害，匪咎。艱則无咎。</p><p>象曰：大有，初九，无交害也。</p><p>子夏：夫欲其豐，害物以求有者，斯害來矣。此害之交也。咎可逃乎。初得於主，始有之矣，守其分而不躁，難其志以自保，則終有大而无咎也。未涉於交害矣。易所以戒。大有，剛健之初，先逺害而利，自至矣。</p><p>九二，大車以載，有攸往，无咎。</p><p>象曰：大車以載，積中不敗也。</p><p>子夏：剛健之中，力之大者也。上之所任事，委於中，致逺，不泥也。</p><p>九三，公用亨于天子，小人弗克。</p><p>象曰：公用亨于天子，小人害也。</p><p>子夏：為下之長，富有其民，公之位也。為五所有，志達乎尊，以奉其主也。小人不可用也。以上之柔德，則不克，通而謀其害之矣。大有，容之也。御小人者，其道異乎，可大有之而不任也。</p><p>九四，匪其彭，无咎。</p><p>象曰：匪其彭，无咎。明辨晳也。</p><p>子夏：柔得尊位，而上下咸願應之以時，近親難處之地也。能知禍福之端，畏天下之所覩。如非在五旁，兢以自警，不敢怙恃，可无咎矣。非明辨者不能至也。可謂智矣。剛能處柔者也。</p><p>六五，厥孚交如，威如，吉。</p><p>象曰：厥孚交如，信以發志也。威如之吉。易而无備也。</p><p>子夏：以柔德而居主位，虚中孚誠民亦奉其誠也。志交信矣。何所備乎。故易然，而保其尊。威如，而獲其吉也。</p><p>上九，自天佑之，吉。无不利。</p><p>象曰：大有，上吉，自天佑也。</p><p>子夏：剛居極上，尊柔奉之，可謂上賢而順高，而得終。履其信也。得其終也。内符於天，與天合德也。則自天佑之矣。何不利焉。</p>',24)])])}const m=a(i,[["render",r]]);export{h as __pageData,m as default};
